-- Deterministic local-development fixture. Never run against production.
set session_replication_role=replica;
on conflict(id) do nothing;
set session_replication_role=origin;









update public.spending_requests set current_draft_revision_id='71000000-0000-0000-0000-000000000001' where id='70000000-0000-0000-0000-000000000001';
update public.spending_requests set current_draft_revision_id='71000000-0000-0000-0000-000000000002' where id='70000000-0000-0000-0000-000000000002';
update public.spending_requests set current_draft_revision_id='71000000-0000-0000-0000-000000000003' where id='70000000-0000-0000-0000-000000000003';
update public.spending_requests set submitted_at=now() where id in('70000000-0000-0000-0000-000000000004','70000000-0000-0000-0000-000000000005');
update public.spending_requests set current_approved_revision_id='71000000-0000-0000-0000-000000000006',submitted_at=now(),approved_at=now() where id='70000000-0000-0000-0000-000000000006';
update public.spending_requests set submitted_at=now() where id='70000000-0000-0000-0000-000000000007';
update public.spending_requests set current_draft_revision_id='71000000-0000-0000-0000-000000000018',submitted_at=now() where id='70000000-0000-0000-0000-000000000008';
update public.spending_requests set current_approved_revision_id='71000000-0000-0000-0000-000000000009',submitted_at=now(),approved_at=now() where id='70000000-0000-0000-0000-000000000009';
update public.spending_requests set current_draft_revision_id='71000000-0000-0000-0000-000000000099' where id='70000000-0000-0000-0000-000000000099';




on conflict(event_id,department_id) do update set next_request_number=excluded.next_request_number,updated_at=now();
